"""按 category 统计 sales.csv 的 count / sum / avg，以 JSON 输出（用户偏好）。"""

import csv
import json
import sys
from collections import OrderedDict


def load_rows(path):
    with open(path, newline="", encoding="utf-8-sig") as f:
        reader = csv.DictReader(f)
        if reader.fieldnames is None:
            raise ValueError("CSV 为空或缺少表头")
        fields = [name.strip() for name in reader.fieldnames]
        if "category" not in fields or "value" not in fields:
            raise ValueError(f"缺少必需列 category/value，实际列: {fields}")
        rows = []
        for lineno, raw in enumerate(reader, start=2):
            row = {k.strip(): v for k, v in raw.items() if k is not None}
            category = (row.get("category") or "").strip()
            value_raw = (row.get("value") or "").strip()
            if not category and not value_raw:
                continue  # 跳过空行
            if not category:
                print(f"[warn] 第 {lineno} 行 category 为空，已跳过", file=sys.stderr)
                continue
            try:
                value = float(value_raw)
            except ValueError:
                print(f"[warn] 第 {lineno} 行 value 非数值 {value_raw!r}，已跳过", file=sys.stderr)
                continue
            rows.append((category, value))
        return rows


def stats_by_category(rows):
    agg = OrderedDict()
    for category, value in rows:
        if category not in agg:
            agg[category] = {"count": 0, "sum": 0.0}
        agg[category]["count"] += 1
        agg[category]["sum"] += value

    result = OrderedDict()
    for category in sorted(agg):
        count = agg[category]["count"]
        total = agg[category]["sum"]
        result[category] = {
            "count": count,
            "sum": round(total, 6),
            "avg": round(total / count, 6) if count else 0.0,
        }
    return result


def main(argv):
    path = argv[1] if len(argv) > 1 else "sales.csv"
    rows = load_rows(path)
    result = stats_by_category(rows)
    print(json.dumps(result, ensure_ascii=False, indent=2))
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv))
"}

